    // =========================================================================
    // 5. BE2 LIVE WI-FI WEBSOCKET & HTTP API INTEGRATION
    // =========================================================================
    const BE2_HOST = "172.18.238.74:8000";
    const BE2_API_URL = `http://${BE2_HOST}/api/memory/graph?task_id=vendor_payout_task`;
    const BE2_WS_URL = `ws://${BE2_HOST}/ws/telemetry`;

    let be2Socket = null;
    let wsReconnectTimeout = null;

    // Requirement 4: Fetch initial graph nodes and coordinates from BE2 API
    async function fetchInitialMemoryGraph() {
      addLog(`Connecting to BE2 API: GET ${BE2_API_URL}...`, "info");
      try {
        const resp = await fetch(BE2_API_URL);
        if (!resp.ok) {
          throw new Error(`HTTP ${resp.status} ${resp.statusText}`);
        }
        const data = await resp.json();
        addLog(`✔ [BE2 API] Successfully fetched initial memory graph for 'vendor_payout_task'`, "success");
        applyBE2GraphData(data);
      } catch (err) {
        addLog(`⚠ [BE2 API] Note: BE2 server unreachable (${err.message}). Using local baseline nodes.`, "warn");
      }
    }

    function applyBE2GraphData(data) {
      let incomingNodes = [];
      if (Array.isArray(data)) {
        incomingNodes = data;
      } else if (data && data.nodes && Array.isArray(data.nodes)) {
        incomingNodes = data.nodes;
      } else if (data && typeof data === "object") {
        incomingNodes = Object.entries(data).map(([key, val]) => ({
          id: key,
          label: val.label || key,
          x: val.x !== undefined ? val.x : val.coord_x,
          y: val.y !== undefined ? val.y : val.coord_y,
          confidence: val.confidence || 1.0
        }));
      }

      if (incomingNodes.length > 0) {
        incomingNodes.forEach(inNode => {
          const existing = memoryNodes.find(n => n.id === inNode.id || n.label.toLowerCase().includes(String(inNode.id).toLowerCase()));
          if (existing) {
            if (inNode.x !== undefined) {
              existing.x = inNode.x > 1 ? inNode.x / 640 : inNode.x;
            }
            if (inNode.y !== undefined) {
              existing.y = inNode.y > 1 ? inNode.y / 480 : inNode.y;
            }
            if (inNode.label) existing.label = inNode.label;
          } else {
            memoryNodes.push({
              id: inNode.id,
              label: inNode.label || inNode.id,
              x: inNode.x > 1 ? inNode.x / 640 : (inNode.x || 0.5),
              y: inNode.y > 1 ? inNode.y / 480 : (inNode.y || 0.5),
              color: "#38bdf8",
              pulse: 0.8,
              connectedTo: ["submit"]
            });
          }
        });

        const cacheBadge = document.getElementById("memory-cache-badge");
        if (cacheBadge) cacheBadge.innerText = `${memoryNodes.length} NODES SYNCED`;
        renderMemoryNodesList();
      }
    }

    function renderMemoryNodesList() {
      const list = document.getElementById("memory-nodes-list");
      if (!list) return;
      list.innerHTML = "";
      memoryNodes.forEach(node => {
        const div = document.createElement("div");
        div.className = "flex justify-between items-center text-slate-300 py-0.5 border-b border-slate-900";
        div.innerHTML = `
          <span style="color: ${node.color}">● node_${node.id}</span>
          <span class="text-slate-500">(x:${Math.round(node.x * 640)}, y:${Math.round(node.y * 480)})</span>
          <span class="text-[10px]" style="color: ${node.color}">SYNCED</span>
        `;
        list.appendChild(div);
      });
    }

    // Requirement 1: WebSocket connection to ws://172.18.238.74:8000/ws/telemetry
    function connectTelemetryWebSocket() {
      if (wsReconnectTimeout) clearTimeout(wsReconnectTimeout);

      const wsBadge = document.getElementById("ws-status-badge");
      const wsText = document.getElementById("ws-status-text");
      const wsDot = document.getElementById("ws-indicator-dot");

      if (be2Socket) {
        try { be2Socket.close(); } catch(e) {}
      }

      if (wsText) wsText.innerText = `WS: CONNECTING (${BE2_HOST})`;
      if (wsBadge) wsBadge.className = "px-3 py-1 rounded-full bg-slate-900 border border-slate-700 text-slate-400 flex items-center space-x-2 font-mono text-[11px]";
      if (wsDot) wsDot.className = "w-2 h-2 rounded-full bg-amber-400 animate-ping";

      try {
        be2Socket = new WebSocket(BE2_WS_URL);

        be2Socket.onopen = () => {
          if (wsText) wsText.innerText = `WS: LIVE (${BE2_HOST})`;
          if (wsBadge) wsBadge.className = "px-3 py-1 rounded-full bg-emerald-950/80 border border-emerald-500/50 text-emerald-300 flex items-center space-x-2 font-mono text-[11px] shadow-[0_0_12px_rgba(16,185,129,0.3)]";
          if (wsDot) wsDot.className = "w-2 h-2 rounded-full bg-emerald-400";
          addLog(`✔ Connected to BE2 WebSocket stream (${BE2_WS_URL})`, "success");
          playSynthSound('blip');
        };

        be2Socket.onmessage = (msg) => {
          let payload = null;
          try {
            payload = JSON.parse(msg.data);
          } catch(e) {
            payload = { event: msg.data };
          }
          handleBE2TelemetryMessage(payload);
        };

        be2Socket.onerror = (err) => {
          if (wsText) wsText.innerText = `WS: OFFLINE (${BE2_HOST})`;
          if (wsBadge) wsBadge.className = "px-3 py-1 rounded-full bg-rose-950/80 border border-rose-500/50 text-rose-300 flex items-center space-x-2 font-mono text-[11px]";
