        be2Socket.onclose = () => {
          if (wsText) wsText.innerText = "WS: RECONNECTING IN 4s...";
          if (wsBadge) wsBadge.className = "px-3 py-1 rounded-full bg-slate-900 border border-amber-700/50 text-amber-400 flex items-center space-x-2 font-mono text-[11px]";
